"""Small, offline-only public adapter around the copied SEB research engine."""
from __future__ import annotations

import csv
import hashlib
import io
import json
import math
from copy import deepcopy
from datetime import UTC, datetime
from pathlib import Path
from typing import Any
from zoneinfo import ZoneInfo

from seb_engine.backtest import Backtester
from seb_engine.data import SyntheticFeed
from seb_engine.features import FeatureEngine
from seb_engine.levels import LevelEngine
from seb_engine.models import Bar
from seb_engine.risk import RiskGuard
from seb_engine.strategies import StrategySuite

ENGINE_VERSION = "seb-research-public-1.0.0"
ROOT = Path(__file__).resolve().parent
CONFIG = ROOT / "frozen_config"
TICK = 0.25
POINT_VALUE = 2.0
REFERENCE_BALANCE = 50_000.0


def _normalized_source_bytes(path: Path) -> bytes:
    """Make source identity independent of Git's Windows/Linux line endings."""
    return _normalize_newlines(path.read_bytes())


def _normalize_newlines(value: bytes) -> bytes:
    return value.replace(b"\r\n", b"\n").replace(b"\r", b"\n")


def _source_digest(paths: list[Path]) -> str:
    return _digest_named_sources([(path.name, _normalized_source_bytes(path)) for path in paths])


def _digest_named_sources(items: list[tuple[str, bytes]]) -> str:
    digest = hashlib.sha256()
    for name, contents in sorted(items, key=lambda item: item[0]):
        digest.update(name.encode() + b"\0" + _normalize_newlines(contents))
    return digest.hexdigest()


def _engine_fingerprint() -> str:
    return _source_digest([ROOT / "public_api.py", *sorted((ROOT / "seb_engine").glob("*.py")), *sorted(CONFIG.glob("*.json"))])


def _hash(value: Any) -> str:
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False).encode()).hexdigest()


def _load(name: str) -> dict[str, Any]:
    return json.loads((CONFIG / name).read_text(encoding="utf-8"))


def _tick(value: float) -> bool:
    return math.isclose(value / TICK, round(value / TICK), abs_tol=1e-8)


def _parse_timestamp(value: Any, row: int) -> datetime:
    if not isinstance(value, str):
        raise ValueError(f"Row {row}: timestamp must be an ISO date and time with a timezone")
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError as exc:
        raise ValueError(f"Row {row}: invalid timestamp") from exc
    if parsed.tzinfo is None or parsed.utcoffset() is None:
        raise ValueError(f"Row {row}: timestamp must include a timezone, for example +00:00 or Z")
    return parsed.astimezone(UTC)


def _number(value: Any, key: str, row: int) -> float:
    if isinstance(value, bool):
        raise ValueError(f"Row {row}: {key} must be a number")
    try:
        number = float(value)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"Row {row}: {key} must be a number") from exc
    if not math.isfinite(number):
        raise ValueError(f"Row {row}: {key} must be finite")
    return number


def _rows(payload: dict[str, Any]) -> list[dict[str, Any]]:
    if "bars" in payload:
        values = payload["bars"]
        if not isinstance(values, list):
            raise ValueError("bars must be a list")
        return values
    source = payload.get("csv")
    if not isinstance(source, str):
        raise ValueError("Provide either bars or csv")
    if len(source.encode("utf-8")) > 5_000_000:
        raise ValueError("CSV is too large; limit it to 20,000 bars")
    reader = csv.DictReader(io.StringIO(source))
    if not reader.fieldnames:
        raise ValueError("CSV needs a header row")
    return list(reader)


def _canonical_bars(payload: dict[str, Any]) -> tuple[list[Bar], list[dict[str, Any]], list[dict[str, Any]]]:
    raw = _rows(payload)
    if not 35 <= len(raw) <= 20_000:
        raise ValueError("Provide between 35 and 20,000 one-minute bars")
    market_tz = ZoneInfo("America/New_York")
    parsed: list[tuple[datetime, dict[str, Any]]] = []
    required = ("open", "high", "low", "close", "volume")
    for row_no, source in enumerate(raw, 1):
        if not isinstance(source, dict):
            raise ValueError(f"Row {row_no}: each bar must be an object")
        timestamp = _parse_timestamp(source.get("timestamp", source.get("time")), row_no)
        values = {key: _number(source.get(key), key, row_no) for key in required}
        if values["volume"] < 0:
            raise ValueError(f"Row {row_no}: volume cannot be negative")
        if values["high"] < max(values["open"], values["close"]) or values["low"] > min(values["open"], values["close"]) or values["low"] > values["high"]:
            raise ValueError(f"Row {row_no}: OHLC prices are inconsistent")
        if not all(_tick(values[key]) for key in ("open", "high", "low", "close")):
            raise ValueError(f"Row {row_no}: MNQ prices must use {TICK:g}-point ticks")
        parsed.append((timestamp, values))
    for index in range(1, len(parsed)):
        if parsed[index][0] <= parsed[index - 1][0]:
            raise ValueError("Bars must be strictly chronological with no duplicate timestamps")
    gaps: list[dict[str, Any]] = []
    segment = 0
    bars: list[Bar] = []
    canonical: list[dict[str, Any]] = []
    for index, (timestamp, values) in enumerate(parsed):
        if timestamp.second or timestamp.microsecond:
            raise ValueError(f"Row {index + 1}: timestamps must be aligned to a full minute")
        if index:
            elapsed_seconds = (timestamp - parsed[index - 1][0]).total_seconds()
            if elapsed_seconds % 60:
                raise ValueError("Timestamps must use an exact whole-minute cadence")
            delta = int(elapsed_seconds // 60)
            if delta != 1:
                segment += 1
                gaps.append({"after": parsed[index - 1][0].isoformat(), "before": timestamp.isoformat(), "missing_minutes": max(0, delta - 1)})
        item = {"timestamp": timestamp.isoformat(), **{key: values[key] for key in required}}
        canonical.append(item)
        bars.append(Bar(timestamp_utc=timestamp, market_time=timestamp.astimezone(market_tz), symbol=f"MNQ-S{segment}", timeframe_minutes=1, source="PUBLIC_RESEARCH_INPUT", is_final=True, **values))
    return bars, canonical, gaps


def generate_sample(seed: int = 7331) -> list[dict[str, Any]]:
    """Return deterministic, tick-aligned synthetic sessions; never market data."""
    feed = SyntheticFeed(seed=seed)
    values = []
    for bar in feed.sessions(count=10, bars_per_session=180):
        values.append({"timestamp": bar.timestamp_utc.isoformat(), "open": round(bar.open / TICK) * TICK, "high": round(bar.high / TICK) * TICK, "low": round(bar.low / TICK) * TICK, "close": round(bar.close / TICK) * TICK, "volume": bar.volume})
    return values


def _engine(settings: dict[str, Any]) -> Backtester:
    risk = deepcopy(_load("risk.json"))
    paper = deepcopy(_load("paper.json"))
    backtest = deepcopy(_load("backtest.json"))
    # Bound only the public report's resampling work. It does not alter a strategy rule.
    backtest["block_bootstrap_samples"] = 250
    backtest["robustness"]["session_block_monte_carlo_samples"] = 250
    risk["estimated_round_trip_commission"] = float(settings["commission_per_contract"])
    risk["slippage_ticks_each_side"] = float(settings["slippage_ticks"])
    configs: dict[str, dict[str, Any]] = {}
    for strategy_id in ("momentum_breakout", "failed_break_reclaim", "balance_rotation"):
        config = deepcopy(_load(f"strategy_{strategy_id}.json"))
        config["version_hash"] = _hash(config)[:16]
        configs[strategy_id] = config
    guard = RiskGuard(risk, account_state_path=None)
    suite = StrategySuite(configs, guard, minimum_target_room_r=float(risk["minimum_target_room_r"]))
    return Backtester(FeatureEngine(), LevelEngine(), suite, backtest, risk, journal=None, paper_config=paper)


def _metric(trades: list[dict[str, Any]]) -> dict[str, Any]:
    net = sum(trade["pnl"] for trade in trades)
    gross = sum(trade["gross_pnl"] for trade in trades)
    costs = sum(trade["costs"] for trade in trades)
    wins = [trade for trade in trades if trade["pnl"] > 0]
    positives = sum(trade["pnl"] for trade in trades if trade["pnl"] > 0)
    negatives = -sum(trade["pnl"] for trade in trades if trade["pnl"] < 0)
    balance = REFERENCE_BALANCE
    peak = balance
    drawdown = 0.0
    for trade in trades:
        balance += trade["pnl"]
        peak = max(peak, balance)
        drawdown = max(drawdown, peak - balance)
    return {"net_pnl": net, "gross_pnl": gross, "costs": costs, "max_drawdown": drawdown, "win_rate": len(wins) / len(trades) if trades else 0.0, "profit_factor": positives / negatives if negatives else None, "trade_count": len(trades), "expectancy_r": sum(trade["result_r"] for trade in trades) / len(trades) if trades else 0.0}


def _globex_session(timestamp: str) -> str:
    local = datetime.fromisoformat(timestamp).astimezone(ZoneInfo("America/New_York"))
    return (local.date().fromordinal(local.date().toordinal() + (1 if local.hour >= 18 else 0))).isoformat()


def _split_metrics(trades: list[dict[str, Any]], bars: list[dict[str, Any]]) -> dict[str, Any]:
    sessions = sorted({_globex_session(bar["timestamp"]) for bar in bars})
    if not sessions:
        return {"design": _metric([]), "validation": _metric([]), "lockbox": _metric([]), "session_boundaries": {"design": [], "validation": [], "lockbox": []}, "out_of_sample_retention": None}
    design_end = max(1, int(len(sessions) * .6))
    validation_end = max(design_end, int(len(sessions) * .8))
    groups = {"design": sessions[:design_end], "validation": sessions[design_end:validation_end], "lockbox": sessions[validation_end:]}
    result = {name: _metric([trade for trade in trades if _globex_session(trade["entry_time"]) in dates]) for name, dates in groups.items()}
    design_r = result["design"]["expectancy_r"]
    result["session_boundaries"] = groups
    result["methodology"] = "POSTHOC_ENTRY_SESSION_SEGMENTS_WITH_POSSIBLE_CARRYOVER"
    result["out_of_sample_retention"] = result["lockbox"]["expectancy_r"] / design_r if design_r > 0 else None
    return result


def run_research(payload: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(payload, dict):
        raise ValueError("payload must be an object")
    settings = {"commission_per_contract": 1.9, "slippage_ticks": 1, "strategy": "combined"}
    supplied_settings = payload.get("settings") or {}
    if not isinstance(supplied_settings, dict) or set(supplied_settings) - set(settings):
        raise ValueError("settings may contain only commission_per_contract, slippage_ticks, and strategy")
    settings.update(supplied_settings)
    if settings["strategy"] not in {"combined", "momentum_breakout", "failed_break_reclaim", "balance_rotation"}:
        raise ValueError("Unknown strategy")
    for field in ("commission_per_contract", "slippage_ticks"):
        if isinstance(settings[field], bool) or not isinstance(settings[field], (int, float)) or not math.isfinite(float(settings[field])) or float(settings[field]) < 0:
            raise ValueError(f"{field} must be a non-negative number")
    if float(settings["commission_per_contract"]) > 100 or float(settings["slippage_ticks"]) > 100 or float(settings["slippage_ticks"]) != int(float(settings["slippage_ticks"])):
        raise ValueError("commission_per_contract must be at most 100 and slippage_ticks must be a whole number from 0 to 100")
    bars, canonical, gaps = _canonical_bars(payload)
    engine = _engine(settings)
    raw = engine.run(bars, strategy_id=settings["strategy"], persist=False)
    records: list[dict[str, Any]] = []
    for source in raw["trades"]:
        quantity = int(source["quantity"])
        costs = float(source["execution_cost_dollars"])
        net = float(source["result_dollars"])
        gross = net + costs
        risk_dollars = abs(float(source["entry"]) - float(source["stop"])) * POINT_VALUE * quantity
        result_r = net / risk_dollars if risk_dollars else 0.0
        conditions = source.get("conditions") or []
        fingerprint = {key: source[key] for key in ("strategy_id", "direction", "entry", "exit", "stop", "target", "entry_time", "exit_time", "quantity")}
        records.append({"id": _hash(fingerprint)[:20], "strategy": source["strategy_id"], "direction": source["direction"], "entry": source["entry"], "exit": source["exit"], "stop": source["stop"], "target": source["target"], "entry_time": source["entry_time"], "exit_time": source["exit_time"], "entry_index": source["entry_index"], "exit_index": source["exit_index"], "quantity": quantity, "pnl": net, "gross_pnl": gross, "costs": costs, "result_r": result_r, "bars_held": source["bars_held"], "exit_reason": source["first_hit"], "evidence": {"conditions": conditions, "features": source["features"]}})
    records.sort(key=lambda trade: (trade["exit_time"], trade["id"]))
    balance = REFERENCE_BALANCE
    peak = balance
    equity = []
    for trade in records:
        balance += trade["pnl"]
        peak = max(peak, balance)
        equity.append({"timestamp": trade["exit_time"], "balance": balance, "drawdown": peak - balance})
    summaries = []
    for strategy in ("momentum_breakout", "failed_break_reclaim", "balance_rotation"):
        group = [trade for trade in records if trade["strategy"] == strategy]
        if group:
            metrics = _metric(group)
            summaries.append({"strategy": strategy, "trade_count": metrics["trade_count"], "net_pnl": metrics["net_pnl"], "win_rate": metrics["win_rate"]})
    dataset = {"label": str(payload.get("label") or "Untitled dataset"), "kind": str(payload.get("kind") or "provided"), "bar_count": len(canonical), "start": canonical[0]["timestamp"], "end": canonical[-1]["timestamp"], "sha256": _hash(canonical)}
    engine_fingerprint = _engine_fingerprint()
    public_engine_version = f"{ENGINE_VERSION}+{engine_fingerprint[:16]}"
    run_id = _hash({"dataset": dataset["sha256"], "settings": settings, "engine_fingerprint": engine_fingerprint})[:24]
    equity.insert(0, {"timestamp": dataset["start"], "balance": REFERENCE_BALANCE, "drawdown": 0.0})
    return {"dataset": dataset, "settings": settings, "engine_version": public_engine_version, "run_id": run_id, "bars": canonical, "trades": records, "equity": equity, "metrics": _metric(records), "strategy_summary": summaries, "split_metrics": _split_metrics(records, canonical), "diagnostics": {"gaps": gaps, "gap_count": len(gaps), "unresolved_open_positions": engine.last_unresolved_positions, "closed_trade_count": len(records), "combined_mode": "INDEPENDENT_STRATEGY_AGGREGATION" if settings["strategy"] == "combined" else "SINGLE_STRATEGY", "engine_fingerprint": engine_fingerprint}, "methodology": ["Offline deterministic research using the copied SEB engine; no broker, live-data, or database connection is created.", "Signals use completed bars and enter on the next bar open after execution-risk revalidation.", "Stops use adverse-first resolution when stop and target occur in the same bar; adverse opening gaps fill at the opening price.", "Gaps split causal histories so no fills are fabricated through missing minutes.", "Combined results aggregate independent strategy simulations and are not a shared-account executable portfolio.", "Split segments are posthoc entry-session summaries and trades may carry over between them.", "Dollar and R results include configured commission and slippage. Equity starts at $50,000 and changes only when a closed trade exits; unresolved positions are excluded."]}

from __future__ import annotations

from collections import defaultdict, deque
from dataclasses import replace
from datetime import datetime, time, timedelta
from typing import Any
from uuid import uuid5, NAMESPACE_URL

from .data import aggregate_bars
from .models import Bar, Direction, Level


def _id(level_type: str, price: float, created: datetime) -> str:
    return str(uuid5(NAMESPACE_URL, f"seb:{level_type}:{price:.8f}:{created.isoformat()}"))


def _level(
    level_type: str,
    price: float,
    created: datetime,
    timeframe: str,
    *,
    dynamic: bool = False,
    tests: int = 0,
) -> Level:
    return Level(
        level_id=_id(level_type, price, created),
        level_type=level_type,
        price=price,
        created_time=created,
        last_updated_time=created,
        source_timeframe=timeframe,
        tests=tests,
        dynamic=dynamic,
    )


class LevelEngine:
    def __init__(
        self,
        opening_range_minutes: int = 30,
        swing_confirmation_bars: int = 2,
        equal_tolerance_ticks: int = 2,
        tick_size: float = 0.25,
        round_number_size: float = 50.0,
    ):
        self.opening_range_minutes = opening_range_minutes
        self.swing_confirmation_bars = swing_confirmation_bars
        self.equal_tolerance = equal_tolerance_ticks * tick_size
        self.round_number_size = round_number_size

    def build(self, features: dict[str, Any]) -> list[Level]:
        bars_1m: list[Bar] = features.get("bars_1m", [])
        bars_5m: list[Bar] = features.get("bars_5m", [])
        if not bars_1m:
            return []
        now = bars_1m[-1].market_time
        levels: list[Level] = []
        levels.extend(self._prior_day_levels(bars_1m, now))
        levels.extend(self._overnight_levels(bars_1m, now))
        levels.extend(self._opening_range(bars_1m, now))
        levels.extend(self._confirmed_swings(bars_1m, "1m"))
        levels.extend(self._confirmed_swings(bars_5m, "5m"))
        levels.extend(self._equal_clusters(levels, now))
        levels.extend(self._round_numbers(bars_1m[-1].close, now))
        levels.extend(self._dynamic_features(features, now))
        unique: dict[tuple[str, int], Level] = {}
        for item in levels:
            unique[(item.level_type, round(item.price / 0.25))] = item
        return sorted(unique.values(), key=lambda item: (item.price, item.level_type))

    def prepare_causal_levels(
        self,
        bars_1m: list[Bar],
        feature_frames: list[tuple[int, dict[str, Any]]],
    ) -> dict[int, list[Level]]:
        """Build replay levels incrementally with confirmation-time causality."""
        bars = sorted((bar for bar in bars_1m if bar.is_final), key=lambda bar: bar.timestamp_utc)
        if not feature_frames:
            return {}
        all_5m = aggregate_bars(bars, 5)
        rth_by_day: dict[Any, list[Bar]] = defaultdict(list)
        overnight_by_day: dict[Any, list[Bar]] = defaultdict(list)
        opening_by_day: dict[Any, list[Bar]] = defaultdict(list)
        for bar in bars:
            local = bar.market_time
            if time(9, 30) < local.time() <= time(16, 0):
                rth_by_day[local.date()].append(bar)
            if time(9, 30) < local.time() <= time(10, 0):
                opening_by_day[local.date()].append(bar)
            overnight_day = (
                local.date() + timedelta(days=1)
                if local.time() > time(18, 0) else local.date()
            )
            overnight_start = datetime.combine(
                overnight_day - timedelta(days=1), time(18, 0), local.tzinfo
            )
            overnight_end = datetime.combine(overnight_day, time(9, 30), local.tzinfo)
            if overnight_start < local <= overnight_end:
                overnight_by_day[overnight_day].append(bar)
        rth_days = sorted(rth_by_day)
        confirmation = self.swing_confirmation_bars
        swings_1m: deque[Level] = deque(maxlen=24)
        swings_5m: deque[Level] = deque(maxlen=24)
        last_1m_confirmation = -1
        last_5m_confirmation = -1
        available_5m = 0
        result: dict[int, list[Level]] = {}

        def add_confirmed(source: list[Bar], confirmed_index: int, timeframe: str, target: deque[Level]) -> None:
            center = confirmed_index - confirmation
            if center < confirmation:
                return
            window = source[center - confirmation: center + confirmation + 1]
            if len(window) != confirmation * 2 + 1:
                return
            pivot = source[center]
            created = source[confirmed_index].market_time
            if pivot.high == max(item.high for item in window) and sum(item.high == pivot.high for item in window) == 1:
                target.append(_level("SWING_HIGH", pivot.high, created, timeframe))
            if pivot.low == min(item.low for item in window) and sum(item.low == pivot.low for item in window) == 1:
                target.append(_level("SWING_LOW", pivot.low, created, timeframe))

        for index, features in feature_frames:
            for confirmed in range(last_1m_confirmation + 1, index + 1):
                add_confirmed(bars, confirmed, "1m", swings_1m)
            last_1m_confirmation = index
            now = bars[index].market_time
            while available_5m < len(all_5m) and all_5m[available_5m].market_time <= now:
                available_5m += 1
            upto_5m = available_5m - 1
            for confirmed in range(last_5m_confirmation + 1, upto_5m + 1):
                add_confirmed(all_5m, confirmed, "5m", swings_5m)
            last_5m_confirmation = max(last_5m_confirmation, upto_5m)

            levels: list[Level] = []
            session_open = datetime.combine(now.date(), time(9, 30), now.tzinfo)
            if now >= session_open:
                prior_days = [day for day in rth_days if day < now.date()]
                if prior_days:
                    session = rth_by_day[prior_days[-1]]
                    levels.extend([
                        _level("PRIOR_DAY_HIGH", max(item.high for item in session), session_open, "RTH"),
                        _level("PRIOR_DAY_LOW", min(item.low for item in session), session_open, "RTH"),
                        _level("PRIOR_DAY_CLOSE", session[-1].close, session_open, "RTH"),
                    ])
                overnight = overnight_by_day.get(now.date(), [])
                if overnight:
                    levels.extend([
                        _level("OVERNIGHT_HIGH", max(item.high for item in overnight), session_open, "GLOBEX"),
                        _level("OVERNIGHT_LOW", min(item.low for item in overnight), session_open, "GLOBEX"),
                    ])
            opening_end = session_open + timedelta(minutes=self.opening_range_minutes)
            opening = opening_by_day.get(now.date(), [])
            if now >= opening_end and opening:
                levels.extend([
                    _level("OPENING_RANGE_HIGH", max(item.high for item in opening), opening_end, f"OR{self.opening_range_minutes}"),
                    _level("OPENING_RANGE_LOW", min(item.low for item in opening), opening_end, f"OR{self.opening_range_minutes}"),
                ])
            levels.extend(swings_1m)
            levels.extend(swings_5m)
            levels.extend(self._equal_clusters(levels, now))
            levels.extend(self._round_numbers(bars[index].close, now))
            levels.extend(self._dynamic_features(features, now))
            unique: dict[tuple[str, int], Level] = {}
            for item in levels:
                unique[(item.level_type, round(item.price / 0.25))] = item
            result[index] = sorted(unique.values(), key=lambda item: (item.price, item.level_type))
        return result

    def _prior_day_levels(self, bars: list[Bar], now: datetime) -> list[Level]:
        by_day: dict[Any, list[Bar]] = defaultdict(list)
        for bar in bars:
            if time(9, 30) < bar.market_time.time() <= time(16, 0):
                by_day[bar.market_time.date()].append(bar)
        prior_days = sorted(day for day in by_day if day < now.date())
        if not prior_days:
            return []
        prior_day = prior_days[-1]
        session = by_day[prior_day]
        created = datetime.combine(now.date(), time(9, 30), now.tzinfo)
        if now < created:
            return []
        return [
            _level("PRIOR_DAY_HIGH", max(bar.high for bar in session), created, "RTH"),
            _level("PRIOR_DAY_LOW", min(bar.low for bar in session), created, "RTH"),
            _level("PRIOR_DAY_CLOSE", session[-1].close, created, "RTH"),
        ]

    def _overnight_levels(self, bars: list[Bar], now: datetime) -> list[Level]:
        start = datetime.combine(now.date() - timedelta(days=1), time(18, 0), now.tzinfo)
        end = datetime.combine(now.date(), time(9, 30), now.tzinfo)
        if now < end:
            return []
        session = [bar for bar in bars if start < bar.market_time <= end]
        if not session:
            return []
        return [
            _level("OVERNIGHT_HIGH", max(bar.high for bar in session), end, "GLOBEX"),
            _level("OVERNIGHT_LOW", min(bar.low for bar in session), end, "GLOBEX"),
        ]

    def _opening_range(self, bars: list[Bar], now: datetime) -> list[Level]:
        start = datetime.combine(now.date(), time(9, 30), now.tzinfo)
        end = start + timedelta(minutes=self.opening_range_minutes)
        if now < end:
            return []
        session = [bar for bar in bars if start < bar.market_time <= end]
        if not session:
            return []
        return [
            _level("OPENING_RANGE_HIGH", max(bar.high for bar in session), end, f"OR{self.opening_range_minutes}"),
            _level("OPENING_RANGE_LOW", min(bar.low for bar in session), end, f"OR{self.opening_range_minutes}"),
        ]

    def _confirmed_swings(self, bars: list[Bar], timeframe: str) -> list[Level]:
        confirmation = self.swing_confirmation_bars
        if len(bars) < confirmation * 2 + 1:
            return []
        result: list[Level] = []
        for center in range(confirmation, len(bars) - confirmation):
            pivot = bars[center]
            window = bars[center - confirmation : center + confirmation + 1]
            created = bars[center + confirmation].market_time
            if pivot.high == max(bar.high for bar in window) and sum(bar.high == pivot.high for bar in window) == 1:
                tests = sum(abs(bar.high - pivot.high) <= self.equal_tolerance for bar in bars[center + 1 :])
                result.append(_level("SWING_HIGH", pivot.high, created, timeframe, tests=tests))
            if pivot.low == min(bar.low for bar in window) and sum(bar.low == pivot.low for bar in window) == 1:
                tests = sum(abs(bar.low - pivot.low) <= self.equal_tolerance for bar in bars[center + 1 :])
                result.append(_level("SWING_LOW", pivot.low, created, timeframe, tests=tests))
        return result[-24:]

    def _equal_clusters(self, levels: list[Level], now: datetime) -> list[Level]:
        result: list[Level] = []
        for kind, target in (("SWING_HIGH", "EQUAL_HIGHS"), ("SWING_LOW", "EQUAL_LOWS")):
            candidates = [level for level in levels if level.level_type == kind]
            for index, left in enumerate(candidates):
                cluster = [right for right in candidates[index + 1 :] if abs(right.price - left.price) <= self.equal_tolerance]
                if cluster:
                    prices = [left.price, *(item.price for item in cluster)]
                    created = max([left.created_time, *(item.created_time for item in cluster)])
                    result.append(_level(target, sum(prices) / len(prices), created, "MIXED", tests=len(prices)))
                    break
        return result

    def _round_numbers(self, price: float, now: datetime) -> list[Level]:
        base = round(price / self.round_number_size) * self.round_number_size
        return [
            _level("ROUND_NUMBER", base + offset * self.round_number_size, now, "PRICE", dynamic=False)
            for offset in (-1, 0, 1)
        ]

    def _dynamic_features(self, features: dict[str, Any], now: datetime) -> list[Level]:
        latest = features.get("latest", {})
        result: list[Level] = []
        for key, kind in (
            ("vwap", "VWAP"),
            ("vwap_plus_1sd", "VWAP_PLUS_1SD"),
            ("vwap_minus_1sd", "VWAP_MINUS_1SD"),
            ("vwap_plus_2sd", "VWAP_PLUS_2SD"),
            ("vwap_minus_2sd", "VWAP_MINUS_2SD"),
        ):
            if latest.get(key) is not None:
                result.append(_level(kind, float(latest[key]), now, "SESSION", dynamic=True))
        for timeframe in ("1m", "5m", "15m"):
            values = features.get("timeframes", {}).get(timeframe, {}).get("latest", {})
            for ema_name in ("ema9", "ema21"):
                if values.get(ema_name) is not None:
                    result.append(_level(f"EMA_{timeframe}_{ema_name[3:]}", float(values[ema_name]), now, timeframe, dynamic=True))
        return result

    @staticmethod
    def expire_stale(levels: list[Level], now: datetime, maximum_age: timedelta) -> list[Level]:
        """Return new immutable level records with causally expired validity state."""
        return [
            replace(level, validity_state="EXPIRED", last_updated_time=now)
            if not level.dynamic and now - level.last_updated_time > maximum_age
            else level
            for level in levels
        ]


def nearest_level(
    levels: list[Level],
    price: float,
    *,
    direction: Direction | None = None,
    allowed_types: set[str] | None = None,
) -> Level | None:
    eligible = [
        level
        for level in levels
        if level.validity_state == "ACTIVE"
        and (not allowed_types or level.level_type in allowed_types)
        and (direction != Direction.LONG or level.price > price)
        and (direction != Direction.SHORT or level.price < price)
    ]
    return min(eligible, key=lambda item: abs(item.price - price)) if eligible else None


def closest_reference(levels: list[Level], price: float, allowed_types: set[str] | None = None) -> Level | None:
    eligible = [
        level for level in levels if level.validity_state == "ACTIVE" and (not allowed_types or level.level_type in allowed_types)
    ]
    return min(eligible, key=lambda item: abs(item.price - price)) if eligible else None

from __future__ import annotations

import json
import math
from dataclasses import dataclass
from pathlib import Path
from typing import Any


@dataclass(frozen=True, slots=True)
class SizingResult:
    quantity: int
    risk_per_contract: float
    total_risk: float
    blocked: bool
    reason: str
    reason_code: str = "OK"
    account_risk_cap: float | None = None


@dataclass(frozen=True, slots=True)
class ExecutionRiskAssessment:
    """Deterministic execution-time bracket, sizing, and account-safety result."""

    quantity: int
    risk_per_contract: float
    total_risk: float
    reward_risk_ratio: float | None
    blocked: bool
    reason_code: str
    reason: str


class RiskGuard:
    def __init__(self, config: dict[str, Any], account_state_path: str | Path | None = None):
        self.config = config
        self.account_state_path = Path(account_state_path) if account_state_path else None

    def account_state(self) -> dict[str, Any]:
        if not self.account_state_path or not self.account_state_path.exists():
            return {}
        try:
            return json.loads(self.account_state_path.read_text(encoding="utf-8-sig"))
        except (OSError, json.JSONDecodeError):
            return {}

    def account_status(self) -> dict[str, str]:
        account = self.account_state()
        if not self.account_state_path:
            return {"status": "NOT_CONFIGURED", "source": "none"}
        if not account:
            return {"status": "UNAVAILABLE", "source": str(self.account_state_path)}
        if account.get("account_locked") or account.get("daily_circuit_breaker_locked"):
            return {"status": "LOCKED_READ_ONLY", "source": str(self.account_state_path)}
        declared = str(account.get("account_status") or "CONNECTED")
        return {"status": f"{declared}_READ_ONLY", "source": str(self.account_state_path)}

    def _account_risk_cap(self, account: dict[str, Any]) -> float | None:
        def remaining_capacity(value: Any) -> float:
            """Treat an explicitly supplied but unusable limit as no capacity."""
            try:
                number = float(value)
            except (TypeError, ValueError):
                return 0.0
            return max(0.0, number) if math.isfinite(number) else 0.0

        caps: list[float] = []
        for key in self.config.get("account_hard_limit_fields", []):
            value = account.get(key)
            if value is not None:
                caps.append(remaining_capacity(value))
        if account.get("current_balance") is not None and account.get("trailing_floor") is not None:
            try:
                trailing_capacity = float(account["current_balance"]) - float(account["trailing_floor"])
            except (TypeError, ValueError):
                trailing_capacity = 0.0
            caps.append(remaining_capacity(trailing_capacity))
        daily_remaining = account.get("daily_loss_remaining")
        if daily_remaining is not None:
            caps.append(remaining_capacity(daily_remaining))
        elif account.get("daily_loss_limit") is not None:
            try:
                limit = abs(float(account["daily_loss_limit"]))
                daily_capacity = limit + min(0.0, float(account.get("daily_pnl", 0.0)))
            except (TypeError, ValueError):
                daily_capacity = 0.0
            caps.append(remaining_capacity(daily_capacity))
        return min(caps) if caps else None

    def size(
        self,
        entry: float,
        stop: float,
        instrument: str = "MNQ",
        *,
        apply_account_constraints: bool = True,
    ) -> SizingResult:
        risk = abs(entry - stop)
        if not math.isfinite(risk) or risk <= 0:
            return SizingResult(
                0, 0.0, 0.0, True, "Stop distance must be positive", "INVALID_STOP"
            )
        point_value = float(self.config.get("point_values", {}).get(instrument, 2.0 if instrument == "MNQ" else 20.0))
        tick_size = float(self.config.get("tick_size", 0.25))
        commission = float(self.config.get("estimated_round_trip_commission", 0.0))
        slippage_ticks = float(self.config.get("slippage_ticks_each_side", 0.0))
        slippage_cost = slippage_ticks * 2.0 * tick_size * point_value
        per_contract = risk * point_value + commission + slippage_cost
        mode = self.config.get("sizing_mode", "FIXED_RISK_DOLLARS")
        if mode == "FIXED_CONTRACTS":
            quantity = int(self.config.get("fixed_contracts", 1))
        else:
            allowed = float(self.config.get("fixed_risk_dollars", 100.0))
            quantity = math.floor(allowed / per_contract)
        quantity = min(quantity, int(self.config.get("maximum_contracts", 1)))
        account_cap: float | None = None
        if apply_account_constraints:
            account = self.account_state()
            if account.get("account_locked"):
                return SizingResult(
                    0, per_contract, 0.0, True,
                    "Read-only account state reports account_locked",
                    "ACCOUNT_LOCKED",
                )
            if account.get("daily_circuit_breaker_locked"):
                return SizingResult(
                    0, per_contract, 0.0, True,
                    "Read-only account state reports daily_circuit_breaker_locked",
                    "DAILY_CIRCUIT_BREAKER_LOCKED",
                )
            account_cap = self._account_risk_cap(account)
            if account_cap is not None:
                quantity = min(quantity, math.floor(account_cap / per_contract))
        if quantity < 1:
            return SizingResult(
                0, per_contract, 0.0, True,
                "Minimum one-contract risk exceeds the global/account limit",
                "ACCOUNT_RISK_CAP" if account_cap is not None else "GLOBAL_RISK_CAP",
                account_cap,
            )
        return SizingResult(
            quantity, per_contract, quantity * per_contract, False,
            "Global sizing method and read-only account caps applied",
            "OK",
            account_cap,
        )

    def assess_execution(
        self,
        *,
        entry: float,
        stop: float,
        target: float,
        direction: str,
        requested_quantity: int,
        instrument: str = "MNQ",
        minimum_reward_risk: float | None = None,
    ) -> ExecutionRiskAssessment:
        """Revalidate a planned order at its actual fill price.

        Quantity can only stay the same or decrease. This method is shared by
        signal-time paper preflight and next-open fill validation so external
        account locks and caps cannot be bypassed between those two moments.
        """
        values = (entry, stop, target)
        if not all(math.isfinite(float(value)) for value in values):
            return ExecutionRiskAssessment(
                0, 0.0, 0.0, None, True, "INVALID_BRACKET",
                "Entry, stop, and target must all be finite",
            )
        normalized_direction = str(getattr(direction, "value", direction)).upper()
        valid_bracket = (
            normalized_direction == "LONG" and stop < entry < target
        ) or (
            normalized_direction == "SHORT" and target < entry < stop
        )
        if not valid_bracket:
            return ExecutionRiskAssessment(
                0, 0.0, 0.0, None, True, "INVALID_BRACKET",
                "Actual next-bar open is outside the planned stop/target bracket",
            )
        tick_size = float(self.config.get("tick_size", 0.25))
        if tick_size <= 0 or any(
            abs(float(value) / tick_size - round(float(value) / tick_size)) > 1e-7
            for value in values
        ):
            return ExecutionRiskAssessment(
                0, 0.0, 0.0, None, True, "TICK_SIZE_COMPLIANCE",
                "Actual entry, stop, and target must align to the configured tick",
            )
        stop_distance = abs(entry - stop)
        reward_distance = abs(target - entry)
        reward_risk = reward_distance / stop_distance if stop_distance > 0 else None
        minimum = float(
            self.config.get("minimum_target_room_r", 1.0)
            if minimum_reward_risk is None else minimum_reward_risk
        )
        if reward_risk is None or reward_risk + 1e-9 < minimum:
            return ExecutionRiskAssessment(
                0, 0.0, 0.0, reward_risk, True, "MINIMUM_REWARD_TO_RISK",
                f"Actual next-bar open leaves less than {minimum:.2f}R of target room",
            )
        if int(requested_quantity) < 1:
            return ExecutionRiskAssessment(
                0, 0.0, 0.0, reward_risk, True, "INVALID_POSITION_SIZE",
                "Planned quantity must be at least one contract",
            )
        sizing = self.size(entry, stop, instrument, apply_account_constraints=True)
        if sizing.blocked:
            return ExecutionRiskAssessment(
                0, sizing.risk_per_contract, 0.0, reward_risk, True,
                sizing.reason_code, sizing.reason,
            )
        quantity = min(int(requested_quantity), int(sizing.quantity))
        fixed_risk = float(self.config.get("fixed_risk_dollars", math.inf))
        if math.isfinite(fixed_risk):
            quantity = min(quantity, math.floor(fixed_risk / sizing.risk_per_contract))
        if quantity < 1:
            return ExecutionRiskAssessment(
                0, sizing.risk_per_contract, 0.0, reward_risk, True,
                "GLOBAL_RISK_CAP",
                "Actual next-bar stop risk exceeds the per-trade risk cap for one contract",
            )
        total_risk = sizing.risk_per_contract * quantity
        return ExecutionRiskAssessment(
            quantity, sizing.risk_per_contract, total_risk, reward_risk, False, "OK",
            "Actual fill bracket, risk, and read-only account limits passed",
        )
